$kind: http-request
order: 1000
method: POST
url: '{{baseUrl}}/api/asistente/preguntar'
headers:
  - key: Content-Type
    value: 'application/json'
  - key: X-Forwarded-For
    value: '203.0.113.200'
body:
  type: json
  content: |-
    {
      "pregunta": "¿Cuál es la nota mínima para aprobar?",
      "usuario": { "rol": "estudiante", "id": "EST-999" }
    }
scripts:
  - type: beforeRequest
    language: text/javascript
    code: |-
      const url = pm.variables.replaceIn("{{baseUrl}}/api/asistente/preguntar");
      const cuerpo = JSON.stringify({ pregunta: "¿Cuál es la nota mínima para aprobar?", usuario: { rol: "estudiante", id: "EST-999" } });
      for (let i = 0; i < 60; i++) {
        await pm.sendRequest({ url, method: "POST", header: { "Content-Type": "application/json", "X-Forwarded-For": "203.0.113." + (i + 1) }, body: { mode: "raw", raw: cuerpo } });
      }
  - type: afterResponse
    language: text/javascript
    code: |-
      pm.test("ESC-084c responde 429", () => pm.response.to.have.status(429));
      pm.test("ESC-084c es un ProblemDetails (RFC 9457)", () => {
        pm.expect(pm.response.headers.get("Content-Type")).to.include("application/problem+json");
        const cuerpo = pm.response.json();
        pm.expect(cuerpo.status).to.eql(429);
        pm.expect(cuerpo.title).to.be.a("string");
      });
      pm.test("ESC-084c sin detalles internos ni stack trace", () => {
        const texto = pm.response.text();
        ["StackTrace", "   at ", "Exception", "System.", "Microsoft.", "TutorFlow.", "localhost:4000", ".cs:line"].forEach((f) => pm.expect(texto).to.not.include(f));
      });
      pm.test("ESC-084c no es una salida del contrato del asistente", () => {
        pm.expect(pm.response.json()).to.not.have.property("respuesta");
      });
      pm.test("ESC-084c incluye Retry-After", () => pm.expect(pm.response.headers.get("Retry-After")).to.be.ok);

