134	    public async Task ESC_084_La_pregunta_61_desde_la_misma_ip_recibe_429_con_retry_after_aunque_cambie_x_forwarded_for()
135	    {
136	        using var fabrica = new FabricaApi();
137	        var ultima = default(RespuestaApi);
138	
139	        for (var i = 1; i <= 61; i++)
140	        {
141	            var encabezados = new Dictionary<string, string> { ["X-Forwarded-For"] = $"203.0.113.{i}" };
142	            ultima = await fabrica.PreguntarAsync("estudiante", "EST-001", Pregunta, "10.0.0.5", encabezados);
143	            Assert.Equal(i == 61 ? 429 : 200, ultima.Estado);
144	        }
